-- ----------------------------
-- Table structure for agv_task_rcs
-- ----------------------------
DROP TABLE IF EXISTS `agv_task_rcs`;
CREATE TABLE `agv_task_rcs`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `req_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '请求编号',
  `req_time` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '请求时间',
  `coo_x` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地码 X 坐标(mm)：任务完成时有值',
  `coo_y` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地码 Y 坐标(mm)：任务完成时有值',
  `current_position_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前位置编号',
  `map_code` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地图编号',
  `map_data_code` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地码编号：任务完成时有值',
  `method` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '方法名, 可使用任务类型做为方法名',
  `pod_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '货架编号：背货架时有值',
  `pod_dir` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `material_lot` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '物料编号',
  `robot_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'AGV 编号（同 agvCode ）',
  `task_code` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前任务单号',
  `wb_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '工作位，一般为机台或工作台位置',
  `state` int(0) NULL DEFAULT 0,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `method`(`method`) USING BTREE,
  INDEX `task_code`(`task_code`) USING BTREE,
  INDEX `current_position_code`(`current_position_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 606870 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '接收agv回传信息表' ROW_FORMAT = Dynamic;

