-- Table structure for call_box_handle
-- ----------------------------
DROP TABLE IF EXISTS `call_box_handle`;
CREATE TABLE `call_box_handle`  (
  `id` bigint(0) NOT NULL,
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '呼叫盒编码',
  `cell_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '呼叫盒的位置编码',
  `call_box_id` bigint(0) NULL DEFAULT NULL,
  `handle_id` bigint(0) NULL DEFAULT NULL,
  `tx_type` int(0) NULL DEFAULT NULL COMMENT '呼叫盒通讯类型 1. tcp/ip 2.其他类型',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `port` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `btn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第几个按钮 0-没有按钮被按 1-第一个按钮 2-第二个按钮',
  `btn_operate` int(0) NULL DEFAULT NULL COMMENT '按钮是否被按下 1-被按下 0-没有被按',
  `btn_state` int(0) NULL DEFAULT NULL COMMENT '按钮按下事件处理状态 0-待处理 1-已处理',
  `class_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `method_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `type` bigint(0) NULL DEFAULT NULL COMMENT '1-cmd_pre  2-cmd 3-success_re 4-success',
  `cmd_index` int(0) NULL DEFAULT NULL COMMENT 'handle的执行顺序',
  `create_time` datetime(0) NULL DEFAULT NULL,
  `create_user_id` bigint(0) NULL DEFAULT NULL,
  `create_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT NULL,
  `update_user_id` bigint(0) NULL DEFAULT NULL,
  `update_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `is_delete` int(0) NULL DEFAULT NULL,
  `version` int(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

