  INDEX `idx_cell_xub`(`sub_x`, `sub_y`, `sub_z`) USING BTREE,
  INDEX `idx_cell_z`(`ware_code`, `z`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6983 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

