-- ----------------------------
DROP TABLE IF EXISTS `cell_link`;
CREATE TABLE `cell_link`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID，自增长',
  `from_cell_id` bigint(0) NOT NULL COMMENT '起始库位ID',
  `to_cell_id` bigint(0) NOT NULL COMMENT '目标库位ID',
  `distance` decimal(10, 2) NULL DEFAULT 1.00 COMMENT '节点间距离，默认1.0',
  `is_blocked` int(0) NULL DEFAULT 0 COMMENT '是否阻塞，0-正常通行，1-阻塞不可通行',
  `ware_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '仓库信息，可存储仓库编号、区域标识等',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '记录创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1087 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '库位邻接关系表，存储四向车调度系统的节点联通关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of cell_link
-- ----------------------------

-- ----------------------------
-- Table structure for cell_record
-- ----------------------------
DROP TABLE IF EXISTS `cell_record`;
CREATE TABLE `cell_record`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `cell_id` bigint(0) NULL DEFAULT NULL COMMENT '库位ID',
  `cell_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库位编码',
  `ware_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库编码',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '日志内容',
  `create_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 59 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库位日志记录表' ROW_FORMAT = Dynamic;

