-- ----------------------------
-- Table structure for device_info
-- ----------------------------
DROP TABLE IF EXISTS `device_info`;
CREATE TABLE `device_info`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `type` int(0) NOT NULL COMMENT '0-堆垛机 1-扫码器 ',
  `com_type` int(0) NOT NULL COMMENT '0-s7 1-modbus tcp 2-mtqq 3-opc da  4-opc ua 5-mc',
  `s7_type` int(0) NULL DEFAULT NULL COMMENT '对应s7 协议 \r\n\r\n0--S200\r\n1--S200_SMART\r\n2--S300\r\n3--S400\r\n4--S1200\r\n5--S1500\r\n6--SINUMERIK_828D\r\n7--\"\"',
  `ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'IP',
  `port` int(0) NULL DEFAULT NULL,
  `is_online` int(0) NOT NULL DEFAULT 0 COMMENT '是否在线 0-否 1-是',
  `state` int(0) NOT NULL DEFAULT 0 COMMENT '0-空闲 1-运行中 2-故障',
  `create_time` datetime(0) NULL DEFAULT NULL,
  `create_user_id` bigint(0) NULL DEFAULT NULL,
  `create_user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT NULL,
  `update_user_id` bigint(0) NULL DEFAULT 0,
  `update_user_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `version` int(0) NOT NULL DEFAULT 0,
  `is_delete` int(0) NOT NULL,
  `task_state` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1000 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of device_info
-- ----------------------------

-- ----------------------------
-- Table structure for device_task_result
-- ----------------------------
DROP TABLE IF EXISTS `device_task_result`;
CREATE TABLE `device_task_result`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `task_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备任务编码',
  `state` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '0' COMMENT '状态 0-初始化 1-已经处理',
  `node` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前位置',
  `type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '类型',
  `create_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `data` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '备注数据',
  `from_device` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备名',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 53043 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of device_task_result
-- ----------------------------

-- ----------------------------
-- Table structure for device_value
-- ----------------------------
DROP TABLE IF EXISTS `device_value`;
CREATE TABLE `device_value`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `device_id` bigint(0) NULL DEFAULT NULL COMMENT '设备id',
  `device_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `device_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `com_type` int(0) NULL DEFAULT NULL COMMENT '通讯方式  同上',
  `s7_type` int(0) NULL DEFAULT NULL COMMENT '对应s7 协议 \r\n\r\n0--s200\r\n1--S200_SMART\r\n2--S300\r\n3--S400\r\n4--S1200\r\n5--S1500\r\n6--SINUMERIK_828D\r\n7--\"\"',
  `ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `port` int(0) NULL DEFAULT NULL,
  `address` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '偏移量 ',
  `bit_index` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '位索引',
  `modbus_type` int(0) NULL DEFAULT NULL COMMENT '字段对应的设备类型\r\n0---输出线圈\r\n1---输入线圈\r\n2---输入寄存器\r\n3---保持寄存器',
  `plc_type` int(0) NULL DEFAULT NULL COMMENT '0 --boolean\r\n1--byte\r\n2--integer\r\n3--short\r\n4--long\r\n5--float\r\n6--double\r\n7--string\r\n8--localDate\r\n9--localTime\r\n10--localDateTime',
  `java_type` int(0) NULL DEFAULT NULL COMMENT '0 --boolean\r\n1--byte\r\n2--integer\r\n3--short\r\n4--long\r\n5--float\r\n6--double\r\n7--string\r\n8--localDate\r\n9--localTime\r\n10--localDateTime',
  `type` int(0) NULL DEFAULT NULL COMMENT '0--(plc->wcs) 1-->(wcs->plc) 2-->(双向)',
  `length` int(0) NOT NULL DEFAULT 0 COMMENT '长度',
  `read_value` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '0',
  `read_time` datetime(0) NULL DEFAULT NULL,
  `write_value` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `write_time` datetime(0) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT NULL,
  `create_user_id` bigint(0) NULL DEFAULT NULL,
  `create_user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT NULL,
  `update_user_id` bigint(0) NULL DEFAULT 0,
  `update_user_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `version` int(0) NOT NULL DEFAULT 0,
  `is_delete` int(0) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9499 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of device_value
-- ----------------------------

