  CONSTRAINT `ds_plan_pallet_ibfk_1` FOREIGN KEY (`plan_id`) REFERENCES `ds_real_plan` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 113 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

