-- ----------------------------
-- Table structure for map_cell_log
-- ----------------------------
DROP TABLE IF EXISTS `map_cell_log`;
CREATE TABLE `map_cell_log`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `operation_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作时间',
  `operation_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作类型  枚举（如INBOUND入库、OUTBOUND出库、ADJUST调整、TRANSFER转移）',
  `status` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '状态  SUCCESS成功、FAILED失败、PENDING处理中',
  `item_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作产品编码',
  `item_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作产品名称',
  `before_quantity` double(10, 3) NULL DEFAULT NULL COMMENT '变更前数量',
  `after_quantity` double(10, 3) NULL DEFAULT NULL COMMENT '变更后数量',
  `change_quantity` double(10, 3) NULL DEFAULT NULL COMMENT '变更数量',
  `map_cell_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '变更库位编码',
  `reference_no` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '关联的订单编号',
  `batch_no` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '变更产品批次号',
  `operate_user_id` bigint(0) NULL DEFAULT NULL COMMENT '操作人id',
  `operate_user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `operator_ip` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人ip',
  `device_info` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '执行操作的设备信息（如 PC、PDA、手机等）',
  `source` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作来源',
  `remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作的补充说明（如调整原因、异常备注等）',
  `create_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `version` int(0) NULL DEFAULT NULL COMMENT '版本号 用于乐观锁控制，防止并发更新冲突',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of map_cell_log
-- ----------------------------

