  `ShelfLifeDays` int(0) NULL DEFAULT NULL COMMENT '最长停放期(小时)',
  `MinShelfLifeDays` int(0) NULL DEFAULT NULL COMMENT '最小停放期\r',
  `AlarmTime` int(0) NULL DEFAULT NULL COMMENT '报警时间小时',
  `IsInUsed` bit(1) NULL DEFAULT NULL COMMENT '是否启用\r',
  `Memo` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `MesCreateTime` datetime(0) NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '创建时间\r',
  `MesCreateName` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建名称',
  `MesUpdateTime` datetime(0) NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `MesUpdateName` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新名称\r',
  `MesDataFlag` tinyint(0) NULL DEFAULT NULL COMMENT '数据标志 0 有效 2删除\r',
  `Version` bigint(0) NULL DEFAULT NULL COMMENT '1',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `AK_ItemId`(`ItemId`, `ItemName`) USING BTREE,
  INDEX `IZ_mes_matinfo_ItemName`(`ItemName`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

