-- ----------------------------
-- Table structure for position_plc_offset
-- ----------------------------
DROP TABLE IF EXISTS `position_plc_offset`;
CREATE TABLE `position_plc_offset`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `position_extend_id` bigint(0) NULL DEFAULT NULL COMMENT '站台扩展ID',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '偏移量编码',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '偏移量名称',
  `address` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '通信地址（PLC中的地址偏移量）',
  `create_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '站台通信偏移量表' ROW_FORMAT = Dynamic;

