-- Records of position_step
-- ----------------------------

-- ----------------------------
-- Table structure for process_node
-- ----------------------------
DROP TABLE IF EXISTS `process_node`;
CREATE TABLE `process_node`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `route_id` bigint(0) NOT NULL COMMENT '工艺流程ID（关联process_route.id）',
  `node_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点编码',
  `node_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点名称',
  `sequence` int(0) NOT NULL COMMENT '顺序号（工艺流程中的顺序）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '节点描述',
  `estimated_time` int(0) NULL DEFAULT 0 COMMENT '预计加工时长（分钟）',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_route_id`(`route_id`) USING BTREE,
  CONSTRAINT `fk_process_node_route_id` FOREIGN KEY (`route_id`) REFERENCES `process_route` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工艺节点表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of process_node
-- ----------------------------

-- ----------------------------
-- Table structure for process_node_position
-- ----------------------------
DROP TABLE IF EXISTS `process_node_position`;
CREATE TABLE `process_node_position`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `node_id` bigint(0) NULL DEFAULT NULL COMMENT '工艺节点ID',
  `position_id` bigint(0) NULL DEFAULT NULL COMMENT '站台ID',
  `fixture_type_id` bigint(0) NULL DEFAULT NULL COMMENT '所需夹具类型ID',
  `priority` int(0) NULL DEFAULT NULL COMMENT '优先级（数字越小优先级越高）',
  `is_enabled` int(0) NULL DEFAULT NULL COMMENT '是否启用（0-禁用 1-启用）',
  `create_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '工艺节点站台关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of process_node_position
-- ----------------------------

-- ----------------------------
-- Table structure for process_route
-- ----------------------------
DROP TABLE IF EXISTS `process_route`;
CREATE TABLE `process_route`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `route_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工艺流程编码（唯一）',
  `route_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工艺流程名称',
  `model_id` bigint(0) NOT NULL COMMENT '适用型号ID（关联product_model.id）',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版本号',
  `status` tinyint(0) NOT NULL DEFAULT 0 COMMENT '状态（0-启用 1-禁用）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '描述',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `create_user_id` bigint(0) NULL DEFAULT NULL COMMENT '创建人ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_route_code`(`route_code`) USING BTREE,
  INDEX `idx_model_id`(`model_id`) USING BTREE,
  CONSTRAINT `fk_process_route_model_id` FOREIGN KEY (`model_id`) REFERENCES `product_model` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工艺流程表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of process_route
-- ----------------------------

-- ----------------------------
-- Table structure for product_model
-- ----------------------------
DROP TABLE IF EXISTS `product_model`;
CREATE TABLE `product_model`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `model_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '型号编码（唯一）',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '型号名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '描述',
  `status` tinyint(0) NOT NULL DEFAULT 0 COMMENT '状态（0-启用 1-禁用）',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `pallet_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `layers` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_code`(`model_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '产品型号表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of product_model
-- ----------------------------

-- ----------------------------
-- Table structure for production_line
-- ----------------------------
DROP TABLE IF EXISTS `production_line`;
CREATE TABLE `production_line`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `production_line_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '产线编码',
  `mark` int(0) NULL DEFAULT NULL COMMENT '阴/阳',
  `create_time` datetime(0) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of production_line
-- ----------------------------

-- ----------------------------
-- Table structure for production_line_xl
-- ----------------------------
DROP TABLE IF EXISTS `production_line_xl`;
CREATE TABLE `production_line_xl`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `line_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产线编码（唯一）',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产线名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '描述',
  `status` tinyint(0) NOT NULL DEFAULT 0 COMMENT '状态（0-启用 1-禁用）',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `create_user_id` bigint(0) NULL DEFAULT NULL COMMENT '创建人ID',
  `create_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建人姓名',
  `is_delete` tinyint(0) NOT NULL DEFAULT 0 COMMENT '删除标志（0-正常 1-删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_line_code`(`line_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '产线表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of production_line_xl
-- ----------------------------

-- ----------------------------
-- Table structure for production_task
-- ----------------------------
DROP TABLE IF EXISTS `production_task`;
CREATE TABLE `production_task`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `task_code` bigint(0) NULL DEFAULT NULL COMMENT '任务编码',
  `wip_id` bigint(0) NULL DEFAULT NULL COMMENT '在制品ID',
  `line_id` bigint(0) NULL DEFAULT NULL COMMENT '产线ID',
  `route_id` bigint(0) NULL DEFAULT NULL COMMENT '工艺流程ID',
  `status` int(0) NULL DEFAULT NULL COMMENT '状态（0-待开始 1-进行中 2-已完成 3-异常 4-取消）',
  `start_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `total_duration` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '总加工时长（分钟）',
  `operator_id` bigint(0) NULL DEFAULT NULL COMMENT '操作人ID',
  `remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '生产任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of production_task
-- ----------------------------

-- ----------------------------
-- Table structure for production_task_detail
-- ----------------------------
DROP TABLE IF EXISTS `production_task_detail`;
CREATE TABLE `production_task_detail`  (
  `id` bigint(0) NOT NULL,
  `task_id` bigint(0) NULL DEFAULT NULL COMMENT '生产任务ID',
  `node_id` bigint(0) NULL DEFAULT NULL COMMENT '工艺节点ID',
  `sequence` int(0) NULL DEFAULT NULL COMMENT '节点顺序',
  `position_id` bigint(0) NULL DEFAULT NULL COMMENT '站台ID',
  `fixture_type_id` bigint(0) NULL DEFAULT NULL COMMENT '使用夹具类型ID',
  `start_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `status` int(0) NULL DEFAULT NULL COMMENT '状态（0-待加工 1-加工中 2-已完成 3-异常 4-跳过）',
  `actual_duration` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '实际加工时长（分钟）',
  `operator_id` int(0) NULL DEFAULT NULL COMMENT '操作人ID',
  `remark` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

