-- ----------------------------
-- Table structure for rcs_car_info
-- ----------------------------
DROP TABLE IF EXISTS `rcs_car_info`;
CREATE TABLE `rcs_car_info`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `device_id` bigint(0) NULL DEFAULT NULL,
  `code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '编码',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '名称',
  `ware_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `rcs_car_type_id` bigint(0) NULL DEFAULT NULL COMMENT '类型ID',
  `disable_state` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '禁用状态',
  `task_state` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务状态',
  `battery_level` int(0) NULL DEFAULT NULL COMMENT '电量',
  `is_charge` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否充电',
  `load_state` int(0) NULL DEFAULT 0 COMMENT '负载状态（0-空载/1-负载）',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` bigint(0) NULL DEFAULT NULL,
  `create_user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_user_id` bigint(0) NULL DEFAULT NULL,
  `update_user_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `version` bigint(0) NULL DEFAULT 0,
  `is_connected` int(0) NULL DEFAULT NULL,
  `current_x` int(0) NULL DEFAULT NULL COMMENT '当前X坐标(mm，下位地图坐标)',
  `current_y` int(0) NULL DEFAULT NULL COMMENT '当前Y坐标(mm，下位地图坐标)',
  `current_z` int(0) NULL DEFAULT NULL COMMENT '当前Z坐标(mm，下位地图坐标)',
  `from_cell_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '起始库位编码',
  `to_cell_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '目标库位编码',
  `z` int(0) NULL DEFAULT NULL,
  `position_ratio` decimal(5, 4) NULL DEFAULT NULL COMMENT '位置插值系数(0-1)：0=起始库位，1=目标库位',
  `move_direction` int(0) NULL DEFAULT NULL COMMENT '移动方向：0-静止 1-右 2-左 3-上 4-下',
  `speed` decimal(10, 2) NULL DEFAULT NULL COMMENT '当前速度(mm/s)',
  `last_update_time` datetime(0) NULL DEFAULT NULL COMMENT '位置最后更新时间',
  `ip` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `port` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_current_z`(`current_z`) USING BTREE,
  INDEX `idx_update_time`(`last_update_time`) USING BTREE,
  INDEX `idx_from_cell`(`from_cell_code`) USING BTREE,
  INDEX `idx_to_cell`(`to_cell_code`) USING BTREE,
  INDEX `location`(`ware_code`, `from_cell_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '车' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rcs_car_info
-- ----------------------------

-- ----------------------------
-- Table structure for rcs_car_job
-- ----------------------------
DROP TABLE IF EXISTS `rcs_car_job`;
CREATE TABLE `rcs_car_job`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '小车任务步骤表',
  `task_id` bigint(0) NULL DEFAULT NULL COMMENT '小车任务id',
  `create_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `allot_car_id` bigint(0) NULL DEFAULT NULL COMMENT '分配的小车id',
  `from_cell_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务起始位置',
  `to_cell_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务终点位置',
  `pallet_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '搬运托盘',
  `status` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务状态（待分配、执行中、暂停、完成、失败）',
  `start_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务开始时间',
  `end_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务结束时间',
  `duration` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '持续时间',
  `error_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '错误代码',
  `error_message` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '错误详情',
  `is_connected` int(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rcs_car_job
-- ----------------------------

