  `ware_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `rcs_car_type_id` bigint(0) NULL DEFAULT NULL COMMENT '使用的车子类型',
  `car_id` bigint(0) NULL DEFAULT NULL COMMENT '当前充电的车子',
