-- ----------------------------

-- ----------------------------
-- Table structure for rcs_map_cell_info
-- ----------------------------
DROP TABLE IF EXISTS `rcs_map_cell_info`;
CREATE TABLE `rcs_map_cell_info`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `cell_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'cellInfo表的外键',
  `map_cell_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地图表的库位编码',
  `map_cell_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地图表的库位名称',
  `ware_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '所属仓库编码',
  `ware_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '所属仓库名称',
  `area_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '所属区域编码',
  `area_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '所属区域名称',
  `map_cell_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地图表库位类型（normal--普通库位）',
  `map_cell_status` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '地图表库位状态 ( AVAILABLE可用、OCCUPIED已占用、MAINTAIN维修中 )',
  `map_cell_x` double(10, 3) NULL DEFAULT NULL COMMENT '地图表坐标X值',
  `map_cell_y` double(10, 3) NULL DEFAULT NULL COMMENT '地图表坐标Y值',
  `allowed_directions` int(0) NULL DEFAULT NULL COMMENT '允许移动的方向用掩码表示(up 0001,down 0010, left 0100, right 1000,all 1111)',
  `map_cell_z` int(0) NULL DEFAULT NULL COMMENT '地图表Z值(层数)',
  `max_capacity` int(0) NULL DEFAULT NULL COMMENT '最大存储容量',
  `current_capacity` int(0) NULL DEFAULT NULL COMMENT '当前存储容量',
  `storage_policy` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'FIFO先进先出、LIFO后进先出、FIXED固定存储',
  `allowed_sku_types` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '限制库位可存放的产品类型(字符串拼接)',
  `priority` int(0) NULL DEFAULT NULL COMMENT '库位的使用优先级',
  `stackable` int(0) NULL DEFAULT NULL COMMENT '是否可堆叠',
  `create_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `create_user_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `remark` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '文本备注',
  `device_id` bigint(0) NULL DEFAULT NULL COMMENT '关联的设备id',
  `car_id` bigint(0) NULL DEFAULT NULL COMMENT '小车主键，用于表示该库位已经被小车锁定',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用于维护四项车地图位置信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rcs_map_cell_info
-- ----------------------------

-- ----------------------------
-- Table structure for rcs_tsj
-- ----------------------------
DROP TABLE IF EXISTS `rcs_tsj`;
CREATE TABLE `rcs_tsj`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '提升机主键',
  `code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '提升机编号',
  `name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '提升机名称',
  `model` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备型号',
  `dock_cell_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '提升机接驳位',
  `cell_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备位置',
  `ware_code` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '仓库编码',
  `ware_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `create_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `status` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '当前状态 空闲 / 运行中 / 故障 / 维护中 / 充电中',
  `current_floor` int(0) NULL DEFAULT NULL COMMENT '当前层数',
  `target_floor` int(0) NULL DEFAULT NULL COMMENT '目标层数',
  `move_direction` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '运行方向  上行 / 下行 / 静止',
  `load_status` int(0) NULL DEFAULT NULL COMMENT '负载状态 布尔值（空载 / 负载中）',
  `real_time_speed` double(10, 3) NULL DEFAULT NULL COMMENT '实时速度',
  `total_operation_time` int(0) NULL DEFAULT NULL COMMENT '累计运行时长  分钟',
  `current_task_id` bigint(0) NULL DEFAULT NULL COMMENT '当前任务ID',
  `task_queue` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '待执行任务列表（JSON 格式）',
  `task_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务类型',
  `task_start_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务启动时间',
  `task_end_time` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '任务完成时间',
  `car_id` bigint(0) NULL DEFAULT NULL COMMENT '关联小车ID',
  `rated_load_capacity` double(10, 3) NULL DEFAULT NULL COMMENT '额定载重 kg',
  `interior_dimensions` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '长 × 宽 × 高（mm）',
  `motor_power` double(10, 3) NULL DEFAULT NULL COMMENT '电机功率 单位：kW',
  `charging_interface_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '充电接口标准',
  `charging_power` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '充电功率',
  `communication_protocol` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '通信协议',
  `positioning_accuracy` int(0) NULL DEFAULT NULL COMMENT '定位精度  定位精度 (mm)',
  `error_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '错误识别码',
  `alarm_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '报警类型枚举',
  `error_message` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '错误信息',
  `authorized_floor_range` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '权限楼层范围  (1,3)',
  `device_code` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'plc设备关联编码',
  `version` int(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rcs_tsj
-- ----------------------------

