-- ----------------------------
-- Table structure for task_define
-- ----------------------------
DROP TABLE IF EXISTS `task_define`;
CREATE TABLE `task_define`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `last_id` bigint(0) NULL DEFAULT NULL,
  `is_judge_step` tinyint(1) NULL DEFAULT 0 COMMENT '是否为判断步骤(0-否, 1-是)',
  `judge_branch_type` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '判断分支类型(success-成功分支, fail-失败分支, null-普通连接)',
  `position_x` decimal(10, 2) NULL DEFAULT NULL COMMENT '节点X坐标',
  `position_y` decimal(10, 2) NULL DEFAULT NULL COMMENT '节点Y坐标',
  `ware_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `area_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
